function historyDialog(){const entries=projectHistory.entries();showDialog('Proje geçmişi',`<div class="dialog-actions"><button id="history-checkpoint">＋ Anlık kayıt</button><button id="history-current-download">Mevcut proje ↓</button></div><div class="history-list">${entries.length?entries.map((e,i)=>`<article class="history-row"><div><strong data-no-translate>${esc(e.name)}</strong><small>${esc(new Date(e.at).toLocaleString('tr-TR'))} · ${esc(e.reason)}</small></div><button data-history-download="${i}" aria-label="${esc(e.name)} geçmiş kaydını indir">↓</button><button data-history-restore="${i}">Aç ↶</button></article>`).join(''):'<p class="support-note">Henüz kayıt yok. Anlık kayıt oluşturun.</p>'}</div>`);$('history-checkpoint').onclick=()=>{try{const added=projectHistory.record(project,'Manuel',true);historyDialog();if(!added)toast('Bu sürüm zaten kayıtlı.');}catch{toast('Geçmiş alanı dolu; projeyi JSON olarak indirin.');}};$('history-current-download').onclick=downloadProject;$('dialog-content').querySelectorAll('[data-history-restore]').forEach(b=>b.onclick=()=>{try{const next=projectHistory.restore(entries[+b.dataset.historyRestore]);if(busy)return toast('Derlemenin bitmesini veya iptal edilmesini bekleyin.');const kept=projectHistory.record(project,'Geri yükleme öncesi',true);if(!kept&&!projectHistory.entries().some(e=>e.text===JSON.stringify(project)))throw Error('Mevcut çalışma geçmişe sığmıyor; önce JSON indirin.');adopt(next);toast('Geçmiş açıldı; önceki çalışma da kaydedildi.');}catch(e){toast(e.message);}});$('dialog-content').querySelectorAll('[data-history-download]').forEach(b=>b.onclick=()=>{try{const e=entries[+b.dataset.historyDownload];projectHistory.restore(e);download(e.name.replace(/[^\p{L}\p{N}_.-]/gu,'_')+'_'+e.at+'.json',e.text,'application/json');}catch(e){toast(e.message);}});}
