function analogScopeCycle(e){const x=scopeX(e),frame=analogHistory.view(traceWindow),cycle=Math.round(frame.start+(x-30)/224*frame.span);if(x<30||x>254||cycle<frame.availableFrom||cycle>frame.end)return null;if(e.shiftKey)return cycle;let closest=null,distance=Infinity;for(const p of frame.points)if(!p.baseline&&!p.gap&&p.cycle>=Math.max(frame.start,frame.availableFrom)&&p.cycle<=frame.end&&Math.abs(p.cycle-cycle)<distance){closest=p;distance=Math.abs(p.cycle-cycle);}return closest?.cycle??cycle;}
